&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Advise on communications and media strategies for the North America Advocacy team, contributing to the formation and execution of political and policy strategies.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134233279&amp;quot;:false,&amp;quot;134245418&amp;quot;:false,&amp;quot;134245529&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Promote, enhance, and protect ONE’s reputation in North America, overseeing strategies to reinforce and defend ONE’s credibility and strengthen ONE’s global brand and position as an advocacy organization.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134233279&amp;quot;:false,&amp;quot;134245418&amp;quot;:false,&amp;quot;134245529&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Contribute the global communications community of practice. Share best practices, strategies, messaging, and products to ensure ONE’s positions are communicated and integrated effectively across departments and regions.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134233279&amp;quot;:false,&amp;quot;134245418&amp;quot;:false,&amp;quot;134245529&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Other duties as assigned by the Director of Communications, North America.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134233279&amp;quot;:false,&amp;quot;134245418&amp;quot;:false,&amp;quot;134245529&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;strong&gt;WHAT WE NEED FROM YOU:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Bachelor’s degree in communications, public relations, journalism, marketing, or a related A master’s degree is preferred but not required.&lt;/li&gt;
&lt;li&gt;8+ years of experience in media, public relations, or journalism, plus 3+ years’ experience managing a team or in a project-lead capacity.&lt;/li&gt;
&lt;li&gt;Proven ability to leverage media relations in order to deliver policy change.&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW215564967 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW215564967 BCX0&quot;&gt;Established network of relationships with key journalists and media&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW215564967 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW215564967 BCX0&quot;&gt;, including but not limited to the Associated Press, Reuters, and other Tier 1 outlets&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW215564967 BCX0&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW215564967 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134233279&amp;quot;:false,&amp;quot;134245418&amp;quot;:false,&amp;quot;134245529&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;Ability to synthesize complicated policy issues into digestible products.&lt;/li&gt;
&lt;li&gt;Experience with both elite and popular media, as well as specialist and non-specialist audiences.&lt;/li&gt;
&lt;li&gt;Excellent track record of developing and delivering effective media strategies.&lt;/li&gt;
&lt;li&gt;Significant experience speaking on the record.&lt;/li&gt;
&lt;li&gt;Significant experience of risk and reputation management, and crisis communications.&lt;/li&gt;
&lt;li&gt;A thorough understanding of the evolving media landscape and the requirements of different kinds of modern media.&lt;/li&gt;
&lt;li&gt;Significant experience working with the political media in North America.&lt;/li&gt;
&lt;li&gt;A strong understanding of the links between policy, advocacy, campaigning, and media work.&lt;/li&gt;
&lt;li&gt;Excellent written and verbal English communication skills, fluency in French is an asset.&lt;/li&gt;
&lt;li&gt;Excellent time management, forward-planning, and prioritization skills.&lt;/li&gt;
&lt;li&gt;Proven ability to work effectively in a team environment and strong interpersonal skills.&lt;/li&gt;
&lt;li&gt;Advanced leadership skills, critical thinking and problem solving.&lt;/li&gt;
&lt;li&gt;High proficiency in Microsoft Office and Google Suite.&lt;/li&gt;
&lt;li&gt;Ability to live and work in the United States, and legal authority to travel to Canada, is required.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 style=&quot;line-height: 1;&quot;&gt;&amp;nbsp;&lt;/h4&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;strong&gt;OTHER ATTRIBUTES:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Related work history in poverty and infectious disease alleviation, advocacy, policy, legislation and/or demonstrable interest in Africa and the issues ONE supports is an asset.&lt;/li&gt;
&lt;li&gt;Ability to maintain the highest degree of confidentiality regarding all aspects of work at all times.&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW208559042 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW208559042 BCX0&quot;&gt;Ability to&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW208559042 BCX0&quot;&gt;work proactively in a collaborative and distributed environment,&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW208559042 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW208559042 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW208559042 BCX0&quot;&gt;manage multiple, shifting priorities under tight deadlines while performing in a fast&lt;/span&gt;&lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW208559042 BCX0&quot;&gt;- paced&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW208559042 BCX0&quot;&gt;, team-oriented environment.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW208559042 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134233279&amp;quot;:false,&amp;quot;134245418&amp;quot;:false,&amp;quot;134245529&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;Collaborative mindset and strong interpersonal skills.&lt;/li&gt;
&lt;li&gt;Critical thinking, communication, and relationship-building skills.&lt;/li&gt;
&lt;li&gt;Analytical, action-oriented, and results focused.&lt;/li&gt;
&lt;li&gt;Highly organized, detail-oriented, and self-motivated.&lt;/li&gt;
&lt;li&gt;Remain positive in high pressure and stressful situations.&lt;/li&gt;
&lt;li&gt;Consistent application of good judgment, and ability to make good and responsible decisions.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;u&gt;COMPENSATION AND BENEFITS:&lt;/u&gt; &lt;/strong&gt;$75,000 - $100,000 annual salary. &lt;em&gt;This salary range is based on compensation survey data for similar organizations and is used to set pay internally at ONE. Where a new hire’s salary falls within this range is based on a variety of factors, including the budget available for this position.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our comprehensive benefits package includes:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Medical, Dental, and Vision Insurance: Coverage to keep you and your family healthy.&lt;/li&gt;
&lt;li&gt;401(k) with Match: Save for retirement with company contributions.&lt;/li&gt;
&lt;li&gt;Flexible Spending Account (FSA): Tax-advantaged savings for eligible expenses.&lt;/li&gt;
&lt;li&gt;Wellness Benefit: Support for your overall well-being.&lt;/li&gt;
&lt;li&gt;Commuter Benefit: Assistance with commuting costs.&lt;/li&gt;
&lt;li&gt;Life Insurance: Financial protection for you and your loved ones.&lt;/li&gt;
&lt;/ul&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;LANGUAGE SKILLS:&lt;/span&gt;&amp;nbsp;&lt;/strong&gt;Fluency in English required. Familiarity with additional languages, especially French, is an asset.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;strong&gt;PHYSICAL REQUIREMENTS/WORK ENVIRONMENT/TRAVEL&lt;/strong&gt;&lt;/span&gt;&lt;strong&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;:&lt;/span&gt;&amp;nbsp;&lt;/strong&gt;Standard office and remote work environment. Reasonable accommodations may be made to enable individuals with disabilities to perform the essential functions of the job. The expectation is to be in the office 3 day per week to ensure tight collaboration and alignment with the US team. Light international and domestic travel is required.&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;strong&gt;APPLICATION INSTRUCTIONS:&lt;/strong&gt;&lt;/span&gt;&lt;strong&gt; &lt;/strong&gt;If you are ready to join the fight against extreme poverty and preventable disease, please submit a resume and cover letter to this opening at &lt;a href=&quot;https://recruiting.ultipro.com/ONE1007/JobBoard/23e61dfc-813d-5e3a-ba93-ec9aa1ee70fa/?q&amp;amp;o=postedDateDesc&quot;&gt;ONE jobs&lt;/a&gt; (&lt;a href=&quot;http://www.one.org/jobs&quot;&gt;http://www.one.org/jobs&lt;/a&gt;).&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div class=&quot;content-conclusion&quot;&gt;
&lt;p&gt;We are committed to providing reasonable accommodations to applicants. When an applicant with a disability needs an accommodation to have an equal opportunity to compete for a job, they may request it orally or in writing (please email recruiting@one.org). ONE will process requests for reasonable accommodation and will provide reasonable accommodations where appropriate, in a prompt and efficient manner.&lt;/p&gt;
&lt;p&gt;We understand that a diversity of strengths, experiences, and backgrounds makes our team stronger. If this position interests you, we encourage you to apply and tell us why you are a great candidate for the role. ONE does not discriminate in its selection and employment practices. We are an equal opportunity employer and all qualified applicants will receive consideration for employment. To learn more about our diversity and inclusion work and priorities, visit &lt;a href=&quot;https://www.one.org/about/diversity&quot; target=&quot;_blank&quot;&gt;https://www.one.org/about/diversity&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Due to the number of inquiries that ONE receives, we thank all candidates for their interest yet only those who are selected for an interview will be contacted. &lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;&lt;/div&gt;

